const slValues = Object.fromEntries(Object.entries(SAMLLAB_ATTRIBUTES).map(([slID, slDefinition]) => [slID, slDefinition.example]));
const slPayload = (slID, slValue = slValues[slID], slDescription) => labP(SAMLLAB_ATTRIBUTES[slID].name, slValue, slDescription, slID);
const slStage = (slID, slTitle, slFrom, slTo, slChannel, slSummary, slDetail, slOperations, slPayloads = [], slChecks = [], slExtra = {}) => {
  // A signed message has one context at creation, transmission and validation.
  // Resolve only the context explicitly supplied to this stage; never carry the
  // previous stage's values into a new response or independent failure branch.
  const slContext = slExtra.attributeValues || {};
  const slShownPayloads = slPayloads.map(slItem => Object.hasOwn(slContext,slItem.attributeId)
    ? {...slItem,value:slContext[slItem.attributeId]} : slItem);
  return {
    ...labStep(slID, slTitle, slFrom, slTo, 'saml', slChannel, slSummary, slDetail, [...new Set(slOperations.map(slAction => slAction.attributeId))], slShownPayloads, slChecks, slOperations), ...slExtra,
    attributeValues:{...slContext,...Object.fromEntries(slShownPayloads.filter(slItem=>slItem.attributeId).map(slItem=>[slItem.attributeId,slItem.value]))},
  };
};
const slMessageValues = (slIDs, slOverrides = {}) => Object.freeze({...Object.fromEntries(slIDs.map(slID=>[slID,slValues[slID]])),...slOverrides});
const slMessageStage = (slContext, ...slArgs) => {
  const slExtra = slArgs[10] || {};
  slArgs[10] = {...slExtra,attributeValues:{...slContext,...(slExtra.attributeValues||{})}};
  return slStage(...slArgs);
};
